steps.tree:
variables    :root { --brand: #E07B1E; }
             used as  color: var(--brand);
             change it once, the whole site follows

pseudo-class :hover  :focus-visible  :nth-child()  :first-child
             a state or a position, not a new element

transition   transition: transform .2s ease;
             smooths a change; goes on the BASE state

animation    @keyframes pulse { from{...} to{...} }
             animation: pulse 1.4s infinite;
             runs on its own, no interaction needed
